"examB-W03-024": "感電防止用漏電斷路器能在漏電時迅速切斷電路，防止感電效果最佳；無熔絲開關、保險絲主要防止過載短路。",
"examA-132": "接地目的：漏電時防止感電、高低壓混觸時讓電流經接地迴路、使保護電驛確實動作；接地與防止機械災害無關。",
